using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEditor;
[InitializeOnLoad]public static class MarinaDetailOptimize{const string D="Assets/Scenes/Oasis/YachtPortAtlas";static Type T=typeof(ReferenceWorkingMarina).GetNestedType("Geo",BindingFlags.NonPublic);static object g;static void B(Vector3 p,Vector3 s,int tile,Color c){T.GetMethod("Box").Invoke(g,new object[]{p,s,tile,c,0f});}static void P(Vector3 a,Vector3 b,float r,int tile,Color c){T.GetMethod("Pole").Invoke(g,new object[]{a,b,r,tile,c,6});}static MarinaDetailOptimize(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("MarinaDetailOptimize.request"))return;File.Delete("MarinaDetailOptimize.request");try{Run();}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/MarinaDetailOptimize.txt",e.ToString());Debug.LogException(e);}}
class Batch{public List<Vector3> p=new List<Vector3>(),n=new List<Vector3>();public List<Vector2> uv=new List<Vector2>();public List<Vector4> flag=new List<Vector4>();public List<Color> c=new List<Color>();public List<int> ids=new List<int>();Dictionary<string,int> map=new Dictionary<string,int>();public void Vertex(Vector3 v,Vector3 norm,Vector2 tex,Vector4 f,Color color){string key=string.Join(",",new[]{v.x,v.y,v.z,norm.x,norm.y,norm.z,tex.x,tex.y,f.x,f.y,f.z,f.w,color.r,color.g,color.b,color.a}.Select(x=>Mathf.RoundToInt(x*100000).ToString()));int index;if(!map.TryGetValue(key,out index)){index=p.Count;map[key]=index;p.Add(v);n.Add(norm);uv.Add(tex);flag.Add(f);c.Add(color);}ids.Add(index);}public Mesh Save(string name){var m=new Mesh{name=name,indexFormat=p.Count<65535?UnityEngine.Rendering.IndexFormat.UInt16:UnityEngine.Rendering.IndexFormat.UInt32};m.SetVertices(p);m.SetNormals(n);m.SetUVs(0,uv);m.SetUVs(1,flag);m.SetColors(c);m.SetTriangles(ids,0);m.RecalculateBounds();m.OptimizeIndexBuffers();m.OptimizeReorderVertexBuffer();AssetDatabase.CreateAsset(m,D+"/Meshes/"+name+".asset");return m;}}
static void Run(){Directory.CreateDirectory("FinalEnvironmentRoadBackup/BeforeMarinaOptimization");File.Copy(D+"/Marina Existing City Props Features.prefab","FinalEnvironmentRoadBackup/BeforeMarinaOptimization/Features.prefab",true);var root=PrefabUtility.LoadPrefabContents(D+"/Marina Existing City Props Features.prefab");var ground=AssetDatabase.LoadAssetAtPath<Mesh>(D+"/Meshes/Grand Ground Level Yacht Yard.asset");float y=ground.vertices.Max(v=>v.y),cx=ground.bounds.center.x,w=ground.bounds.size.x,d=ground.bounds.size.z;Color metal=new Color(.2f,.24f,.24f),yellow=new Color(.95f,.65f,.08f);g=Activator.CreateInstance(T);
foreach(float x in new[]{cx+17,cx+38,cx+60}){float z=d/2-3;B(new Vector3(x,y+.7f,z),new Vector3(.55f,1.4f,.4f),-1,metal);B(new Vector3(x,y+1.5f,z),new Vector3(.8f,.28f,.55f),-1,Color.white);B(new Vector3(x,y+1.5f,z-.3f),new Vector3(.43f,.14f,.02f),-1,new Color(.025f,.13f,.15f));P(new Vector3(x+.3f,y+.75f,z),new Vector3(x+1.2f,y+.3f,z),.035f,-1,new Color(.045f,.04f,.035f));B(new Vector3(x,y+.025f,z),new Vector3(1.3f,.04f,1.1f),-1,yellow);}
// Mooring cleats with solid curved hose guides along berth entrances.
for(float x=cx-w/2+6;x<cx+w/2-4;x+=10){float z=-d/2+1.7f;P(new Vector3(x,y+.05f,z),new Vector3(x,y+.28f,z),.09f,2,Color.white);P(new Vector3(x-.38f,y+.28f,z),new Vector3(x+.38f,y+.28f,z),.08f,2,Color.white);}
// Office facade trim, wall fittings, canopy supports and roof louvers.
float ox=-8*.65f-204.5909f*.175f,oz=77.98045f*.3f*.65f;foreach(float x in new[]{ox-8,ox+8}){B(new Vector3(x,y+2.65f,oz-6.5f),new Vector3(.38f,.7f,.23f),-1,metal);B(new Vector3(x,y+2.65f,oz-6.65f),new Vector3(.23f,.45f,.06f),-1,new Color(.95f,.78f,.43f));P(new Vector3(x,y+.4f,oz-6.7f),new Vector3(x,y+3.4f,oz-6.7f),.04f,-1,metal);}for(int k=0;k<16;k++)B(new Vector3(ox-10+k*1.3f,y+7.58f,oz),new Vector3(.075f,.035f,10),-1,new Color(.45f,.45f,.42f));
var detail=new GameObject("Fine marina service pedestals cleats and office fittings");detail.transform.SetParent(root.transform,false);var detailMesh=(Mesh)T.GetMethod("Save").Invoke(g,new object[]{"Marina fine fittings before optimization"});detail.AddComponent<MeshFilter>().sharedMesh=detailMesh;var mat=AssetDatabase.LoadAssetAtPath<Material>(D+"/Shared Yacht Yard Atlas.mat");detail.AddComponent<MeshRenderer>().sharedMaterial=mat;
int beforeRender=root.GetComponentsInChildren<MeshRenderer>().Length,beforeVerts=0,beforeTri=0;var near=new Dictionary<string,Batch>();var far=new Dictionary<string,Batch>();foreach(var f in root.GetComponentsInChildren<MeshFilter>()){var m=f.sharedMesh;var pp=m.vertices;var nn=m.normals;var tt=m.uv;var flags=new List<Vector4>();m.GetUVs(1,flags);var cc=m.colors;var ids=m.triangles;beforeVerts+=pp.Length;beforeTri+=ids.Length/3;var matrix=root.transform.worldToLocalMatrix*f.transform.localToWorldMatrix;bool keep=!f.name.StartsWith("Existing Striped")&&!f.name.StartsWith("Existing Traffic")&&!f.name.StartsWith("Existing Yellow")&&!f.name.StartsWith("Fine marina")&&!f.name.StartsWith("Marina service");for(int j=0;j<ids.Length;j+=3){var center=matrix.MultiplyPoint3x4((pp[ids[j]]+pp[ids[j+1]]+pp[ids[j+2]])/3);string key=Mathf.FloorToInt((center.x-(cx-w/2))/35)+"_"+Mathf.FloorToInt((center.z+d/2)/35);Batch a;if(!near.TryGetValue(key,out a)){a=new Batch();near[key]=a;}Batch b=null;if(keep&&!far.TryGetValue(key,out b)){b=new Batch();far[key]=b;}for(int k=0;k<3;k++){int i=ids[j+k];var p=matrix.MultiplyPoint3x4(pp[i]);var n=matrix.MultiplyVector(nn[i]).normalized;var uv=tt.Length>i?tt[i]:Vector2.zero;var flag=flags.Count>i?flags[i]:new Vector4(-1,0,0,0);var color=cc.Length>i?cc[i]:Color.white;a.Vertex(p,n,uv,flag,color);if(keep)b.Vertex(p,n,uv,flag,color);}}}
foreach(var t in root.transform.Cast<Transform>().ToArray())UnityEngine.Object.DestroyImmediate(t.gameObject);int afterVerts=0,farTri=0;foreach(var pair in near){var sector=new GameObject("Optimized marina sector "+pair.Key);sector.transform.SetParent(root.transform,false);var n=new GameObject("Near detail");n.transform.SetParent(sector.transform,false);var mesh=pair.Value.Save("Marina optimized near "+pair.Key);afterVerts+=mesh.vertexCount;n.AddComponent<MeshFilter>().sharedMesh=mesh;var nr=n.AddComponent<MeshRenderer>();nr.sharedMaterial=mat;var lod=sector.AddComponent<LODGroup>();Batch fb;if(far.TryGetValue(pair.Key,out fb)){var f=new GameObject("Far structure");f.transform.SetParent(sector.transform,false);var fm=fb.Save("Marina optimized far "+pair.Key);farTri+=fm.triangles.Length/3;f.AddComponent<MeshFilter>().sharedMesh=fm;var fr=f.AddComponent<MeshRenderer>();fr.sharedMaterial=mat;lod.SetLODs(new[]{new LOD(.12f,new[]{nr}),new LOD(.004f,new[]{fr})});}else lod.SetLODs(new[]{new LOD(.04f,new[]{nr})});lod.RecalculateBounds();}
mat.enableInstancing=true;EditorUtility.SetDirty(mat);string atlas=D+"/Shared Yacht Yard Atlas.png";var imp=(TextureImporter)AssetImporter.GetAtPath(atlas);imp.isReadable=false;imp.mipmapEnabled=true;imp.streamingMipmaps=true;imp.anisoLevel=4;foreach(string platform in new[]{"Android","iPhone"})imp.SetPlatformTextureSettings(new TextureImporterPlatformSettings{name=platform,overridden=true,maxTextureSize=2048,format=TextureImporterFormat.ASTC_6x6});imp.SaveAndReimport();PrefabUtility.SaveAsPrefabAsset(root,D+"/Marina Existing City Props Features.prefab");PrefabUtility.UnloadPrefabContents(root);AssetDatabase.SaveAssets();File.WriteAllText("FinalEnvironmentRoadReview/MarinaDetailOptimize.txt","SUCCESS added shore power pedestals cables cleats office wall fittings and rooftop louvers.\nRenderers before="+beforeRender+"; near spatial batches="+near.Count+"; source vertices="+beforeVerts+"; welded near vertices="+afterVerts+"; near triangles="+beforeTri+"; far triangles="+farTri+".\nOne atlas/material; 16-bit indices where possible; sorted GPU indices; spatial near/far LOD; ASTC6x6 streaming mipmaps; no added realtime lights; native prop template prefabs preserved.");}
